import{Z as a,e as t,f as i,a0 as o}from"./chunks/framework.DmpHOl9T.js";const m=JSON.parse('{"title":"Email Notifications","description":"","frontmatter":{},"headers":[],"relativePath":"forms/email-notifications.md","filePath":"forms/email-notifications.md","lastUpdated":1782532814000}'),n={name:"forms/email-notifications.md"};function s(r,e,l,h,c,d){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="email-notifications" tabindex="-1">Email Notifications <a class="header-anchor" href="#email-notifications" aria-label="Permalink to &quot;Email Notifications&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For deliverability, branded templates, PDF attachments, and programmatic setup, see <a href="/guides/email-notifications/">Guides → Email Notifications</a>.</p></div><p>Email notifications let a form send email when a submission happens.</p><p>A single form can have multiple notifications, which means one form can often cover several email jobs without needing separate forms for each variation.</p><p>Typical notification patterns include sending a confirmation to the person who submitted the form, sending an internal copy to a team inbox, or sending different messages depending on the answers in the form.</p><p>When you are setting notifications up, most of the work comes down to four things:</p><ul><li>who should receive the email</li><li>when the email should send</li><li>what content should be included</li><li>whether attachments or a PDF should be added</li></ul><h2 id="recipients" tabindex="-1">Recipients <a class="header-anchor" href="#recipients" aria-label="Permalink to &quot;Recipients&quot;">​</a></h2><p>Recipients can be fixed, conditional, or both.</p><p>That means you can often keep one notification and branch the recipients based on form answers, instead of creating a separate notification for every small variation.</p><p>If the email should only send for certain submissions, use <a href="/forms/conditions">Conditions</a>.</p><h2 id="email-content" tabindex="-1">Email Content <a class="header-anchor" href="#email-content" aria-label="Permalink to &quot;Email Content&quot;">​</a></h2><p>The content editor stays fairly simple on purpose, so the email is more likely to work across mail clients.</p><p>Use the <a href="/developers/reference-tokens">variable picker</a> to insert field values, submission details, site and user values, summary selectors, and custom variables.</p><p>If you need more control over the outer email layout, move that concern into an email template rather than trying to make the content field do everything.</p><h2 id="templates-and-pdfs" tabindex="-1">Templates and PDFs <a class="header-anchor" href="#templates-and-pdfs" aria-label="Permalink to &quot;Templates and PDFs&quot;">​</a></h2><p>A notification can also use:</p><ul><li>an email template to wrap the message</li><li>a PDF template when you want to attach a generated PDF</li></ul><p>That keeps the notification focused on who gets the email and what it should contain, while the template controls presentation.</p><h2 id="preview-and-test-send" tabindex="-1">Preview and Test Send <a class="header-anchor" href="#preview-and-test-send" aria-label="Permalink to &quot;Preview and Test Send&quot;">​</a></h2><p>Use the preview tab when you want a quick check of the rendered output with sample content.</p><p>Use a test send when you want to check real delivery, styling, or mail-provider behaviour before relying on the notification in production.</p><p><span id="queue-behavior"></span></p><h2 id="queue-behaviour" tabindex="-1">Queue Behaviour <a class="header-anchor" href="#queue-behaviour" aria-label="Permalink to &quot;Queue Behaviour&quot;">​</a></h2><p>Formie can send notifications through Craft’s queue. That is usually the better choice because it keeps submission requests faster for the person filling out the form.</p><p>If email delivery feels slow or unreliable, check the queue and mailer setup before assuming the notification itself is wrong.</p>',26)])])}const u=a(n,[["render",s]]);export{m as __pageData,u as default};
